pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        vm.deal(address(this), 100 ether);
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(uint256 value, bytes32 hash, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(value <= 1000 ether);
        vm.assume(actor != address(c));

        uint256 balanceBefore = address(c).balance;
        vm.deal(actor, value);
        vm.prank(actor);
        bool ok = false;
        try c.lockInGuess{value: value}(hash) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: the contract balance must reflect the correct accounting.
        // After a call to lockInGuess, if it succeeds, the contract must have received exactly 1 ether.
        // If it fails, the contract balance must remain unchanged.
        if (ok) {
            assertEq(address(c).balance, balanceBefore + 1 ether, "Balance must increase by 1 ether on success");
        } else {
            assertEq(address(c).balance, balanceBefore, "Balance must remain unchanged on failure");
        }
    }
}

