pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = (new C){value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, uint8 fuzzBlockOffset) public {
        // restrict fuzzBlockOffset to avoid block.number underflow while keeping domain wide
        vm.assume(fuzzBlockOffset <= 200);
        uint256 snapshot = vm.snapshot();

        // advance block number by a fuzzed amount
        vm.roll(block.number + fuzzBlockOffset);

        // lock in a guess
        vm.prank(address(0x1));
        vm.deal(address(0x1), 1 ether);
        c{value: 1 ether}(address(0x1)); // unnecessary but valid, no lockInGuess yet
        vm.prank(address(0x1));
        vm.deal(address(0x1), 1 ether);
        c.lockInGuess{value: 1 ether}(hash);

        // attempt settle
        vm.prank(address(0x1));
        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }

        // revert to snapshot to isolate the test
        vm.revertTo(snapshot);

        // property: settle never succeeds immediately after lockInGuess because guessed block is in the past
        assertTrue(!settled);
    }
}

