pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint8 blockAdvance) public {
        // Create a fresh player who will lock a guess
        address player = address(uint160(uint256(keccak256(abi.encode(hash, blockAdvance)))));
        vm.assume(player != address(0) && player != address(c));
        // Advance at least 1 block past the lock-in block (lockInGuess sets guesses[msg.sender].block = block.number + 1)
        // blockAdvance is a small uint8 to keep search space bounded but wide enough
        vm.assume(blockAdvance >= 2);

        // Fund player with exactly 1 ether to lock a guess
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(hash);

        // Warp to a block where settlement is allowed
        vm.roll(block.number + blockAdvance);

        // The answer at settlement is keccak256(blockhash(block.number - blockAdvance + 1))
        // If hash matches the answer, the correct contract pays 2 ether to the player during settle
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - blockAdvance + 1)));

        uint256 balanceBefore = player.balance;
        vm.prank(player);
        c.settle();
        uint256 balanceAfter = player.balance;

        if (hash == answer) {
            // For a correct guess, the reference pays out 2 ether.
            // The bug never stores the guess, so the guess is always zero and never matches answer.
            // Thus the bug never pays out.
            assertTrue(balanceAfter == balanceBefore + 2 ether);
        } else {
            // For an incorrect guess, neither version pays out.
            // The property still holds: balance unchanged.
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

