pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, bytes32 hash) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));

        uint256 snapshot = vm.snapshot();

        vm.deal(sender, 5 ether);
        vm.prank(sender);
        c.lockInGuess{value: 1 ether}(hash);

        vm.roll(block.number + 2);

        address payable spender = payable(sender);
        uint256 balanceBefore = spender.balance;

        vm.prank(sender);
        c.settle();

        uint256 balanceAfter = spender.balance;

        // If the guess is correct (i.e. the stored guess matches the blockhash of the lock-in block),
        // the balance must increase by 2 ether. Otherwise, the balance must remain the same (no transfer).
        // In the reference contract, a correct guess leads to a 2 ether increase.
        // In the buggy contract, the guess is never stored (remains zero), so it can never match a non-zero blockhash.
        // Thus, for any hash that equals the blockhash of the lock-in block, the reference contract increases balance by 2 ether,
        // while the buggy contract does not transfer anything. This asserts that the balance change is correct.
        if (hash == keccak256(abi.encodePacked(blockhash(block.number - 1)))) {
            assertTrue(balanceAfter - balanceBefore == 2 ether);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }

        vm.revertTo(snapshot);
    }
}

