        vm.assume(actor != address(0) && actor != address(this));
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(0x1234)));
        vm.roll(block.number + blockJump);
        vm.prank(actor);
        bool ok = true;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
