contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address target, uint256 ethAmount) public {
        require(ethAmount > 0);
        require(address(this).balance >= ethAmount);
        bool reverted;
        uint256 beforeBalance = target.balance;
        assembly {
            let success := call(gas(), sload(c.slot), ethAmount, 0, 0, 0, 0)
            reverted := iszero(success)
        }
        bytes memory payload = abi.encodeWithSignature("settle()");
        (bool ok,) = address(c).call(payload);
        uint256 afterBalance = target.balance;
        assert(!reverted || !ok || !(afterBalance > beforeBalance));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        bool reverted; try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}
